import { useState } from 'react';
import { Download, FileDown, Network } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';

/** Module-oriented diagram exports generated by the local server. */
export function ExportMenu() {
  const [group, setGroup] = useState<'stage' | 'file'>('stage');
  const query = `?group=${group}`;
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button size="sm" variant="outline" aria-label="导出 draw.io 或 XMind">
          <Download className="size-3.5" /><span className="max-md:hidden">导出</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent side="bottom" align="end" sideOffset={8} className="w-72 p-3">
        <p className="m-0 text-[12px] font-medium">按功能模块导出</p>
        <p className="m-0 mt-1 text-[10.5px] leading-4 text-muted-foreground">每个模块包含该阶段的实现函数；draw.io 为多页图，XMind 为模块树。</p>
        <label className="mt-2 flex items-center gap-2 text-[11px] text-muted-foreground">
          分组
          <select value={group} onChange={(event) => setGroup(event.target.value as 'stage' | 'file')} className="h-7 rounded-md border bg-card px-1.5 text-[11px] text-foreground">
            <option value="stage">按攻击阶段</option>
            <option value="file">按文件</option>
          </select>
        </label>
        <div className="mt-2 flex flex-col gap-1.5">
          <a href={`/api/export/drawio${query}`} download className="flex items-center gap-2 rounded-md border bg-card px-2.5 py-2 text-[12px] transition-colors hover:border-strong">
            <FileDown className="size-3.5 text-node-unit" />
            <span className="min-w-0 flex-1">draw.io 多页图</span>
            <span className="font-mono text-[10px] text-muted-foreground">.drawio</span>
          </a>
          <a href={`/api/export/xmind${query}`} download className="flex items-center gap-2 rounded-md border bg-card px-2.5 py-2 text-[12px] transition-colors hover:border-strong">
            <Network className="size-3.5 text-node-stage" />
            <span className="min-w-0 flex-1">XMind 思维导图</span>
            <span className="font-mono text-[10px] text-muted-foreground">.xmind</span>
          </a>
        </div>
      </PopoverContent>
    </Popover>
  );
}
